-- =====================================================================
-- ChillTechnologies ERP - CAPA C: ChillDrive (producto estrella)
-- Rediseno NORMALIZADO del backend real de la app.
-- PostgreSQL. PK: int GENERATED BY DEFAULT AS IDENTITY (forma moderna de serial).
-- Cambios vs la BD improvisada:
--   * Los enums con atributos propios pasan a tablas CATALOGO con FK
--     (planes, niveles, tipos_evento, tipos_vehiculo, tipos_conductor,
--      categorias_aliado, metodos_pago, posiciones_camara).
--   * Los 'estado' (maquinas de estado cerradas) se quedan como CHECK.
--   * Se conservan FKs, indices, el libro mayor de puntos y las vistas.
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- =====================================================================
-- CATALOGOS
-- =====================================================================

CREATE TABLE planes (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre        varchar(30)  NOT NULL UNIQUE,
    precio_soles  numeric(8,2) NOT NULL DEFAULT 0 CHECK (precio_soles >= 0),
    descripcion   varchar(200)
);

CREATE TABLE tipos_conductor (
    id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  varchar(30) NOT NULL UNIQUE
);

CREATE TABLE tipos_vehiculo (
    id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  varchar(30) NOT NULL UNIQUE
);

CREATE TABLE niveles (
    id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         varchar(20) NOT NULL UNIQUE,
    puntos_minimos integer NOT NULL DEFAULT 0 CHECK (puntos_minimos >= 0)
);

CREATE TABLE tipos_evento (
    id                     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre                 varchar(60) NOT NULL UNIQUE,
    impacto_puntaje_default integer NOT NULL DEFAULT 0
);

CREATE TABLE categorias_aliado (
    id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  varchar(50) NOT NULL UNIQUE
);

CREATE TABLE metodos_pago (
    id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  varchar(30) NOT NULL UNIQUE
);

CREATE TABLE posiciones_camara (
    id      integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  varchar(30) NOT NULL UNIQUE
);

-- =====================================================================
-- NUCLEO: usuarios (conductores) y su gamificacion
-- =====================================================================

CREATE TABLE usuarios (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombres           varchar(100) NOT NULL,
    apellidos         varchar(100) NOT NULL,
    correo            varchar(150) NOT NULL UNIQUE,
    password_hash     varchar(255) NOT NULL,
    telefono          varchar(20),
    foto_perfil       varchar(255),
    plan_id           integer NOT NULL REFERENCES planes (id) ON UPDATE CASCADE,
    tipo_conductor_id integer NOT NULL REFERENCES tipos_conductor (id) ON UPDATE CASCADE,
    estado            varchar(20) NOT NULL DEFAULT 'Activo'
                      CHECK (estado IN ('Activo','Inactivo','Suspendido')),
    ultimo_acceso     timestamp,
    fecha_registro    timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_usuarios_estado ON usuarios (estado);
COMMENT ON TABLE usuarios IS 'Conductores registrados en ChillDrive';

CREATE TABLE suscripciones (
    id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id      integer NOT NULL REFERENCES usuarios (id) ON UPDATE CASCADE ON DELETE CASCADE,
    fecha_inicio    date NOT NULL,
    fecha_fin       date NOT NULL,
    monto_soles     numeric(8,2) NOT NULL DEFAULT 15.00 CHECK (monto_soles > 0),
    metodo_pago_id  integer NOT NULL REFERENCES metodos_pago (id) ON UPDATE CASCADE,
    estado          varchar(20) NOT NULL DEFAULT 'Activa'
                    CHECK (estado IN ('Activa','Vencida','Cancelada')),
    referencia_pago varchar(100),
    fecha_registro  timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_suscripciones_fechas CHECK (fecha_fin > fecha_inicio)
);
CREATE INDEX idx_suscripciones_usuario ON suscripciones (usuario_id);
CREATE INDEX idx_suscripciones_estado  ON suscripciones (estado);
CREATE INDEX idx_suscripciones_fin     ON suscripciones (fecha_fin);
COMMENT ON TABLE suscripciones IS 'Ciclos de pago del plan Profesional';

CREATE TABLE vehiculos (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id        integer NOT NULL REFERENCES usuarios (id) ON UPDATE CASCADE ON DELETE CASCADE,
    placa             varchar(15) NOT NULL UNIQUE,
    marca             varchar(50),
    modelo            varchar(50),
    anio              integer CHECK (anio IS NULL OR (anio BETWEEN 1980 AND 2100)),
    color             varchar(30),
    tipo_vehiculo_id  integer NOT NULL REFERENCES tipos_vehiculo (id) ON UPDATE CASCADE,
    estado            varchar(20) NOT NULL DEFAULT 'Activo'
                      CHECK (estado IN ('Activo','Inactivo','Vendido')),
    fecha_registro    timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_vehiculos_usuario ON vehiculos (usuario_id);
COMMENT ON TABLE vehiculos IS 'Vehiculos registrados por cada conductor';

CREATE TABLE camaras (
    id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vehiculo_id    integer NOT NULL REFERENCES vehiculos (id) ON UPDATE CASCADE ON DELETE CASCADE,
    nombre         varchar(100),
    direccion_ip   varchar(50),
    posicion_id    integer NOT NULL REFERENCES posiciones_camara (id) ON UPDATE CASCADE,
    estado         varchar(20) NOT NULL DEFAULT 'Desconectada'
                   CHECK (estado IN ('Conectada','Desconectada','Error')),
    fecha_registro timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE camaras IS 'Dispositivos de captura de video por vehiculo';

CREATE TABLE viajes (
    id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id         integer NOT NULL REFERENCES usuarios (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    vehiculo_id        integer NOT NULL REFERENCES vehiculos (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    fecha_inicio       timestamp NOT NULL,
    fecha_fin          timestamp,
    distancia_km       numeric(10,2) CHECK (distancia_km IS NULL OR distancia_km >= 0),
    duracion_minutos   integer CHECK (duracion_minutos IS NULL OR duracion_minutos >= 0),
    puntaje_conduccion numeric(5,2) CHECK (puntaje_conduccion IS NULL OR (puntaje_conduccion BETWEEN 0 AND 100)),
    puntos_ganados     integer NOT NULL DEFAULT 0 CHECK (puntos_ganados >= 0),
    estado             varchar(20) NOT NULL DEFAULT 'En Curso'
                       CHECK (estado IN ('En Curso','Finalizado','Cancelado')),
    CONSTRAINT chk_viajes_fechas CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
);
CREATE INDEX idx_viajes_usuario      ON viajes (usuario_id);
CREATE INDEX idx_viajes_vehiculo     ON viajes (vehiculo_id);
CREATE INDEX idx_viajes_estado       ON viajes (estado);
CREATE INDEX idx_viajes_fecha_inicio ON viajes (fecha_inicio DESC);
COMMENT ON COLUMN viajes.puntaje_conduccion IS 'Score 0-100 generado por modelo de IA en tiempo real';

CREATE TABLE eventos (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    viaje_id          integer REFERENCES viajes (id) ON UPDATE CASCADE ON DELETE SET NULL,
    camara_id         integer NOT NULL REFERENCES camaras (id) ON UPDATE CASCADE ON DELETE CASCADE,
    tipo_evento_id    integer NOT NULL REFERENCES tipos_evento (id) ON UPDATE CASCADE,
    impacto_puntaje   integer NOT NULL DEFAULT 0,
    latitud           numeric(10,7),
    longitud          numeric(10,7),
    foto_evidencia    varchar(255),
    fecha_evento      timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cliente_evento_id varchar(64)
);
CREATE INDEX idx_eventos_viaje  ON eventos (viaje_id);
CREATE INDEX idx_eventos_camara ON eventos (camara_id);
CREATE INDEX idx_eventos_fecha  ON eventos (fecha_evento DESC);
CREATE UNIQUE INDEX uq_eventos_cliente_evento_id ON eventos (cliente_evento_id)
    WHERE cliente_evento_id IS NOT NULL;
COMMENT ON COLUMN eventos.viaje_id IS 'NULL si la deteccion ocurre fuera de un viaje activo';

CREATE TABLE puntos_usuario (
    usuario_id           integer PRIMARY KEY REFERENCES usuarios (id) ON UPDATE CASCADE ON DELETE CASCADE,
    puntos_actuales      integer NOT NULL DEFAULT 0 CHECK (puntos_actuales >= 0),
    puntos_historicos    integer NOT NULL DEFAULT 0 CHECK (puntos_historicos >= 0),
    nivel_id             integer NOT NULL REFERENCES niveles (id) ON UPDATE CASCADE,
    ultima_actualizacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON COLUMN puntos_usuario.puntos_historicos IS 'Acumulado total; no baja con canjes. Determina nivel y ranking.';

-- =====================================================================
-- Economia de recompensas
-- =====================================================================

CREATE TABLE aliados (
    id                  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre              varchar(100) NOT NULL,
    ruc                 varchar(11) UNIQUE,
    categoria_id        integer NOT NULL REFERENCES categorias_aliado (id) ON UPDATE CASCADE,
    direccion           varchar(200),
    distrito            varchar(60),
    telefono            varchar(20),
    email               varchar(150),
    logo                varchar(255),
    descripcion         text,
    comision_porcentaje numeric(5,2) NOT NULL DEFAULT 10.00 CHECK (comision_porcentaje BETWEEN 0 AND 100),
    estado              varchar(20) NOT NULL DEFAULT 'Activo'
                        CHECK (estado IN ('Activo','Inactivo','Suspendido')),
    fecha_registro      timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE premios (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    aliado_id         integer NOT NULL REFERENCES aliados (id) ON UPDATE CASCADE ON DELETE CASCADE,
    nombre            varchar(150) NOT NULL,
    descripcion       text,
    puntos_requeridos integer NOT NULL CHECK (puntos_requeridos > 0),
    stock             integer NOT NULL DEFAULT 0 CHECK (stock >= 0),
    fecha_inicio      date,
    fecha_fin         date,
    imagen            varchar(255),
    estado            varchar(20) NOT NULL DEFAULT 'Disponible'
                      CHECK (estado IN ('Disponible','Agotado','Vencido','Pausado')),
    fecha_registro    timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_premios_fechas CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
);
CREATE INDEX idx_premios_aliado ON premios (aliado_id);
CREATE INDEX idx_premios_estado ON premios (estado);

CREATE TABLE canjes (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id        integer NOT NULL REFERENCES usuarios (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    premio_id         integer NOT NULL REFERENCES premios (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    puntos_utilizados integer NOT NULL CHECK (puntos_utilizados > 0),
    codigo_qr         varchar(64) NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(16), 'hex'),
    fecha_canje       timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_uso         timestamp,
    estado            varchar(20) NOT NULL DEFAULT 'Pendiente'
                      CHECK (estado IN ('Pendiente','Usado','Expirado','Anulado'))
);
CREATE INDEX idx_canjes_usuario ON canjes (usuario_id);
CREATE INDEX idx_canjes_premio  ON canjes (premio_id);
CREATE INDEX idx_canjes_estado  ON canjes (estado);

CREATE TABLE movimientos_puntos (
    id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id       integer NOT NULL REFERENCES usuarios (id) ON UPDATE CASCADE ON DELETE RESTRICT,
    tipo             varchar(20) NOT NULL CHECK (tipo IN ('Ganado','Canjeado','Ajuste','Expirado')),
    puntos           integer NOT NULL CHECK (puntos <> 0),
    descripcion      varchar(255),
    viaje_id         integer REFERENCES viajes (id) ON UPDATE CASCADE ON DELETE SET NULL,
    canje_id         integer REFERENCES canjes (id) ON UPDATE CASCADE ON DELETE SET NULL,
    fecha_movimiento timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_movpuntos_coherencia CHECK (
        (tipo = 'Ganado'   AND puntos > 0) OR
        (tipo = 'Canjeado' AND puntos < 0) OR
        (tipo IN ('Ajuste','Expirado'))
    )
);
CREATE INDEX idx_movpuntos_usuario ON movimientos_puntos (usuario_id);
CREATE INDEX idx_movpuntos_viaje   ON movimientos_puntos (viaje_id);
CREATE INDEX idx_movpuntos_canje   ON movimientos_puntos (canje_id);
CREATE INDEX idx_movpuntos_fecha   ON movimientos_puntos (fecha_movimiento DESC);
COMMENT ON TABLE movimientos_puntos IS 'Libro mayor inmutable: cada fila es una transaccion de puntos';

-- =====================================================================
-- VISTAS
-- =====================================================================

CREATE VIEW v_ranking_conductores AS
SELECT u.id AS usuario_id,
       u.nombres || ' ' || u.apellidos AS conductor,
       tc.nombre AS tipo_conductor,
       pu.puntos_actuales,
       pu.puntos_historicos,
       n.nombre AS nivel,
       round(avg(v.puntaje_conduccion), 2) AS puntaje_promedio,
       count(v.id) AS total_viajes
FROM usuarios u
    JOIN puntos_usuario pu  ON pu.usuario_id = u.id
    JOIN niveles n          ON n.id = pu.nivel_id
    JOIN tipos_conductor tc ON tc.id = u.tipo_conductor_id
    LEFT JOIN viajes v      ON v.usuario_id = u.id AND v.estado = 'Finalizado'
GROUP BY u.id, u.nombres, u.apellidos, tc.nombre, pu.puntos_actuales, pu.puntos_historicos, n.nombre
ORDER BY pu.puntos_historicos DESC;

CREATE VIEW v_suscripciones_activas AS
SELECT u.id AS usuario_id,
       u.nombres || ' ' || u.apellidos AS conductor,
       u.correo,
       s.id AS suscripcion_id,
       s.fecha_inicio,
       s.fecha_fin,
       s.monto_soles,
       mp.nombre AS metodo_pago,
       s.fecha_fin - CURRENT_DATE AS dias_restantes
FROM suscripciones s
    JOIN usuarios u     ON u.id = s.usuario_id
    JOIN metodos_pago mp ON mp.id = s.metodo_pago_id
WHERE s.estado = 'Activa'
ORDER BY s.fecha_fin;

